import{Z as o,e as a,f as t,a0 as r}from"./chunks/framework.DmpHOl9T.js";const h=JSON.parse('{"title":"How to Keep Email Notifications Out of Your Junk Emails","description":"","frontmatter":{},"headers":[],"relativePath":"guides/email-notifications/how-to-keep-email-notifications-out-of-your-junk-emails.md","filePath":"guides/email-notifications/how-to-keep-email-notifications-out-of-your-junk-emails.md","lastUpdated":1782532814000}'),i={name:"guides/email-notifications/how-to-keep-email-notifications-out-of-your-junk-emails.md"};function s(n,e,d,l,m,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="how-to-keep-email-notifications-out-of-your-junk-emails" tabindex="-1">How to Keep Email Notifications Out of Your Junk Emails <a class="header-anchor" href="#how-to-keep-email-notifications-out-of-your-junk-emails" aria-label="Permalink to &quot;How to Keep Email Notifications Out of Your Junk Emails&quot;">​</a></h1><p>Spam filters are good at separating legitimate mail from junk — but Formie notification settings can still work against you if they look like spoofed or misconfigured messages. These tips help your Formie emails arrive in the inbox.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="/forms/email-notifications">Email Notifications</a> configured on at least one form</li><li>A working Craft mail transport (not PHP <code>mail()</code> on a shared host)</li></ul><h2 id="use-a-third-party-mailer" tabindex="-1">Use a Third-Party Mailer <a class="header-anchor" href="#use-a-third-party-mailer" aria-label="Permalink to &quot;Use a Third-Party Mailer&quot;">​</a></h2><p>Sendmail on a server rarely cuts it. Even a well-tuned server setup is usually less reliable than a provider dedicated to delivery.</p><p>Use Mailgun, SendGrid, Amazon SES, Postmark, or any transport Craft supports. Do not compromise on delivery for notification mail.</p><h2 id="do-not-use-the-submitter-s-email-as-the-from-address" tabindex="-1">Do Not Use the Submitter&#39;s Email as the &quot;from&quot; Address <a class="header-anchor" href="#do-not-use-the-submitter-s-email-as-the-from-address" aria-label="Permalink to &quot;Do Not Use the Submitter&#39;s Email as the &quot;from&quot; Address&quot;">​</a></h2><p>A common mistake is putting the user-provided email in <strong>From</strong> so admins can hit Reply. That hurts deliverability badly.</p><p>Receiving servers compare the sending IP and the domain in <strong>From</strong>. If they do not match — for example, mail sent from your server claiming to be <code>@gmail.com</code> — the message looks suspicious. Some providers block it outright.</p><p>Use a consistent <strong>From</strong> address you control, such as <code>notifications@yourdomain.com</code>. Put the submitter&#39;s address in <strong>Reply-To</strong> instead for the same reply behaviour.</p><h2 id="do-not-duplicate-addresses-across-from-to-cc-and-bcc" tabindex="-1">Do Not Duplicate Addresses Across from, to, CC, and BCC <a class="header-anchor" href="#do-not-duplicate-addresses-across-from-to-cc-and-bcc" aria-label="Permalink to &quot;Do Not Duplicate Addresses Across from, to, CC, and BCC&quot;">​</a></h2><p>Some providers flag messages when the same address appears in multiple recipient fields, or when <strong>From</strong> matches <strong>To</strong>.</p><p>Do not CC an address that is already in <strong>To</strong>.</p><h2 id="set-up-spf-dkim-and-dmarc" tabindex="-1">Set Up SPF, DKIM, and DMARC <a class="header-anchor" href="#set-up-spf-dkim-and-dmarc" aria-label="Permalink to &quot;Set Up SPF, DKIM, and DMARC&quot;">​</a></h2><p>Domain-level authentication has a real impact on inbox placement:</p><ul><li><a href="https://www.cloudflare.com/learning/dns/dns-records/dns-spf-record/" target="_blank" rel="noreferrer">Sender Policy Framework (SPF)</a></li><li><a href="https://www.cloudflare.com/learning/dns/dns-records/dns-dkim-record/" target="_blank" rel="noreferrer">DomainKeys Identified Mail (DKIM)</a></li><li><a href="https://www.cloudflare.com/learning/dns/dns-records/dns-dmarc-record/" target="_blank" rel="noreferrer">Domain-based Message Authentication, Reporting and Conformance (DMARC)</a></li></ul><p>Configure these for the domain you send from.</p><h2 id="only-send-from-an-address-you-are-allowed-to-use" tabindex="-1">Only Send from an Address You Are Allowed to Use <a class="header-anchor" href="#only-send-from-an-address-you-are-allowed-to-use" aria-label="Permalink to &quot;Only Send from an Address You Are Allowed to Use&quot;">​</a></h2><p>Your <strong>From</strong> domain must match what your mail provider authorises. You cannot reliably send as <code>@example.com</code> unless you control that domain&#39;s DNS and provider settings.</p>',20)])])}const p=o(i,[["render",s]]);export{h as __pageData,p as default};
